#!/usr/bin/env bash
# Agent environment setup — ONE script that takes a fresh machine to "build and tests run".
# Generated by /ai-init from this project's verified commands; yours to edit.
# Target: .ai-init/agent-setup.sh — used by every place an agent starts cold:
#   .devcontainer/devcontainer.json            postCreateCommand
#   .github/workflows/copilot-setup-steps.yml  GitHub Copilot coding agent
#   Codex cloud / Claude Code on the web       environment "setup script": bash .ai-init/agent-setup.sh
#
# Rules: non-interactive, idempotent (safe to run twice), no secrets, no production access.
# It ends with a smoke test, so a broken environment fails HERE — not halfway through a task.
#
set -euo pipefail
CALLER_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
SCRIPT_ROOT="$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/.." && pwd))"
cd "${CALLER_ROOT:-$SCRIPT_ROOT}"
step() { printf '\n==> %s\n' "$*"; }
need() { command -v "$1" >/dev/null 2>&1 || { echo "Missing $1 — $2" >&2; exit 1; }; }

step "Runtime"; need java "install the JDK version from pom.xml"; java -version 2>&1 | head -n1
MVN=mvn; [ -x ./mvnw ] && MVN=./mvnw
step "Dependencies (cached for offline work)"; $MVN -B -q dependency:go-offline
step "Warm build (compile, no tests)"; $MVN -B -q -DskipTests compile

step "Guardrails"
# Installs the pre-commit hook in this clone (no-op when guardrails are not installed).
if [ -f .ai-init/hooks/guard.sh ]; then bash .ai-init/hooks/guard.sh install-git-hook; else echo "(not installed)"; fi

step "Smoke test"
mvn -B -q -DskipTests compile

echo
echo "Agent environment ready."
